# Prompt (summary): Run Snow unit test binaries with clean colored output and Valgrind leak check.
# Changes: added file.
"""Run Snow unit test binaries and print a clean summary.

Usage:
    python scripts/run_unit.py [--valgrind | --no-valgrind]
        [--timeout SECS] [--verbose]

Binaries are read from the Makefile TEST_BUILD_DIR (build/<os>/tests).

Exit code is 0 only when every binary passes and no leaks are reported.
Valgrind output is captured to per-binary log files, never interleaved
with the summary. If valgrind is missing, tests run without it once a
single warning line is printed.
"""

import argparse
import os
import platform
import re
import shutil
import signal
import subprocess
import sys
import tempfile


def _use_color():
    if os.environ.get("FORCE_COLOR"):
        return True
    if os.environ.get("NO_COLOR"):
        return False
    try:
        return sys.stdout.isatty()
    except (OSError, ValueError):
        return False


_COLOR = _use_color()


def _paint(code, text):
    return f"\x1b[{code}m{text}\x1b[0m" if _COLOR else text


def _tag(status):
    if status == "PASS":
        return _paint("32", "[PASS]")
    if status in ("FAIL", "TIMEOUT"):
        return _paint("31", f"[{status}]")
    return f"[{status}]"


_WIN_FATAL = {
    0xC0000005: "ACCESS_VIOLATION",
    0xC00000FD: "STACK_OVERFLOW",
    0xC0000094: "INT_DIVIDE_BY_ZERO",
}


def _crash_name(returncode):
    """Name a fatal exit code, or None if the process exited normally."""
    if returncode < 0:
        try:
            return signal.Signals(-returncode).name
        except ValueError:
            return f"signal {-returncode}"
    if returncode >= 0xC0000000:
        return _WIN_FATAL.get(
            returncode, f"NTSTATUS 0x{returncode:08X}"
        )
    return None

VALGRIND_FLAGS = [
    "--leak-check=full",
    "--show-leak-kinds=all",
    "--track-origins=yes",
    # NOTE: no --errors-for-leaks (unknown to old valgrind); leaks are
    # detected by parsing byte counts from the log instead.
    "--error-exitcode=99",
]
# 99 is safe here: Snow test binaries exit 0/1, unlike the ifj26
# compiler which reserves 99 for internal errors (see run_e2e.py).
VALGRIND_ERROR_EXIT = 99
SNOW_ARGS = ["--no-color", "--no-timer", "--no-maybes", "--no-cr", "--quiet"]
TOTAL_RE = re.compile(r"Total: Passed (\d+)/(\d+) tests")
LEAK_RE = re.compile(r"(definitely|indirectly|possibly|still reachable) lost: ([\d,]+) bytes")
FRAME_RE = re.compile(r"==\d+==\s+(?:at|by) 0x[0-9A-Fa-f]+: (\S+) \(([^()]+)\)")
# Valgrind frames that never point at user code.
_NON_USER_FILES = ("vg_replace_malloc.c", "snow.h")


def _leak_site(log):
    """File:line of the first user-code frame in a leak record, if any."""
    for line in log.splitlines():
        match = FRAME_RE.search(line)
        if not match:
            continue
        _func, where = match.group(1), match.group(2).strip()
        if where.startswith("in ") or ":" not in where:
            continue
        if os.path.basename(where.split(":")[0]) in _NON_USER_FILES:
            continue
        return where
    return None


BUILD_DIR = os.path.join("build", platform.system().lower(), "tests")


def discover_binaries(build_dir):
    names = []
    for entry in sorted(os.listdir(build_dir)):
        if not entry.startswith("test_"):
            continue
        path = os.path.join(build_dir, entry)
        if not os.path.isfile(path):
            continue
        if entry.endswith(".exe"):
            # Windows test binary.
            names.append(path)
        elif "." not in entry and os.access(path, os.X_OK):
            # POSIX test binary (extensionless executable).
            names.append(path)
    return names


def parse_snow_total(output):
    match = TOTAL_RE.search(output)
    if match:
        return int(match.group(1)), int(match.group(2))
    return None


def parse_valgrind_log(log_path):
    """Return (leaked_bytes, detail); None bytes means the log is unusable."""
    try:
        with open(log_path, "r", errors="replace") as handle:
            log = handle.read()
    except OSError:
        return None, "unreadable log"
    if "definitely lost:" not in log and "no leaks are possible" not in log:
        return None, "no leak summary in log"
    total = 0
    kinds = []
    for match in LEAK_RE.finditer(log):
        nbytes = int(match.group(2).replace(",", ""))
        total += nbytes
        if nbytes > 0:
            kinds.append(f"{match.group(1)} lost: {nbytes}B")
    if total == 0:
        return 0, "none"
    site = _leak_site(log)
    detail = ", ".join(kinds)
    if site is not None:
        detail += f" @ {site}"
    return total, detail


def run_one(binary, use_valgrind, timeout, log_dir):
    name = os.path.basename(binary)
    command = [binary] + SNOW_ARGS
    valgrind_log = None
    if use_valgrind:
        valgrind_log = os.path.join(log_dir, name + ".valgrind.log")
        command = (
            ["valgrind"]
            + VALGRIND_FLAGS
            + ["--log-file=" + valgrind_log]
            + command
        )
    try:
        proc = subprocess.run(
            command, capture_output=True, text=True, timeout=timeout, check=False
        )
    except subprocess.TimeoutExpired:
        return {
            "name": name,
            "status": "TIMEOUT",
            "passed": False,
            "leaked": False,
            "info": f"timed out after {timeout}s",
        }
    output = (proc.stdout or "") + (proc.stderr or "")
    total = parse_snow_total(output)
    # --error-exitcode masks the child exit code whenever valgrind itself
    # reports errors, so read Snow pass/fail from its output in that case.
    errored = use_valgrind and proc.returncode == VALGRIND_ERROR_EXIT
    if errored:
        if total is not None:
            passed = total[0] == total[1]
        else:
            passed = False
    else:
        passed = proc.returncode == 0
    leaked = False
    leak_info = ""
    if use_valgrind and valgrind_log is not None:
        leak_bytes, detail = parse_valgrind_log(valgrind_log)
        if leak_bytes is None:
            leaked = True
            leak_info = detail
        elif leak_bytes > 0:
            leaked = True
            leak_info = f"{leak_bytes}B ({detail})"
    if total is not None:
        info = f"{total[0]}/{total[1]} snow tests"
    else:
        crash = _crash_name(proc.returncode)
        if crash is not None:
            info = f"crashed ({crash}), later tests in binary did not run"
        else:
            info = f"exit {proc.returncode}"
    if leak_info:
        info += ", valgrind: " + leak_info
    elif errored:
        info += ", valgrind errors"
    status = "PASS" if (passed and not leaked and not errored) else "FAIL"
    return {
        "name": name,
        "status": status,
        "passed": passed,
        "leaked": leaked,
        "info": info,
        "output": output,
    }


def main(argv=None):
    parser = argparse.ArgumentParser(description="Run Snow unit tests.")
    parser.add_argument(
        "--valgrind", dest="valgrind", action="store_true", default=True
    )
    parser.add_argument(
        "--no-valgrind", dest="valgrind", action="store_false"
    )
    parser.add_argument("--timeout", type=int, default=60)
    parser.add_argument("--verbose", action="store_true")
    args = parser.parse_args(argv)

    if not os.path.isdir(BUILD_DIR):
        print(f"FAIL: build directory '{BUILD_DIR}' not found")
        return 2
    binaries = discover_binaries(BUILD_DIR)
    if not binaries:
        print(f"FAIL: no test binaries in '{BUILD_DIR}'")
        return 2

    use_valgrind = args.valgrind
    if use_valgrind and shutil.which("valgrind") is None:
        print(_paint("33", "WARN: valgrind not found, running without leak check"))
        use_valgrind = False

    results = []
    with tempfile.TemporaryDirectory(prefix="unit_valgrind_") as log_dir:
        for binary in binaries:
            result = run_one(binary, use_valgrind, args.timeout, log_dir)
            results.append(result)
            if result["leaked"]:
                leak_tag = _paint("31", "leaks: yes")
            else:
                leak_tag = "leaks: none"
            print(
                "{} {} ({}, {})".format(_tag(result["status"]), result["name"], result["info"], leak_tag)
            )
            if result["status"] != "PASS" and result["output"].strip():
                print("\n".join("    " + line for line in result["output"].splitlines()[:40]).rstrip())
            if args.verbose and result["status"] != "PASS":
                log_path = os.path.join(
                    log_dir, result["name"] + ".valgrind.log"
                )
                if os.path.isfile(log_path):
                    print("--- valgrind log: {} ---".format(result["name"]))
                    with open(log_path, errors="replace") as handle:
                        print(handle.read()[:4000].rstrip())
                    print("--- end valgrind log ---")

    passed = sum(1 for r in results if r["status"] == "PASS")
    leaked = sum(1 for r in results if r["leaked"])
    if use_valgrind:
        summary = f"unit: {passed}/{len(results)} passed, {leaked} with leaks"
    else:
        summary = f"unit: {passed}/{len(results)} passed"
    print(_paint("32" if passed == len(results) else "31", summary))
    return 0 if passed == len(results) else 1


if __name__ == "__main__":
    sys.exit(main())
